
using System.Collections;
using UnityEngine;
using UnityEngine.UI;

// Generated by ChatGPT
public class EnvironmentalMessages : MonoBehaviour
{
    [Header("Message Settings")]
    [SerializeField] private Text messageText;
    [SerializeField] private float messageDuration = 3f;

    private readonly string[] messages =
    {
        "¡Estas recuperando el bosque!",
        "¡Cada residuo cuenta!",
        "¡Buen trabajo, guardian del bosque!",
        "¡La naturaleza te lo agradece!",
        "¡Estas ayudando al planeta!"
    };

    private Coroutine messageCoroutine;
    private int lastMessageIndex = -1;

    private void Awake()
    {
        if (messageText != null)
            messageText.gameObject.SetActive(false);
    }

    private void OnEnable()
    {
        Collectible.Collected += OnWasteCollected;
    }

    private void OnDisable()
    {
        Collectible.Collected -= OnWasteCollected;

        if (messageCoroutine != null)
            StopCoroutine(messageCoroutine);
    }

    private void OnWasteCollected(Collectible collectible)
    {
        if (messageText == null || messages.Length == 0)
            return;

        int index = Random.Range(0, messages.Length);

        if (messages.Length > 1 && index == lastMessageIndex)
            index = (index + 1) % messages.Length;

        lastMessageIndex = index;

        if (messageCoroutine != null)
            StopCoroutine(messageCoroutine);

        messageCoroutine = StartCoroutine(
            ShowMessage(messages[index])
        );
    }

    private IEnumerator ShowMessage(string message)
    {
        messageText.text = message;
        messageText.gameObject.SetActive(true);

        yield return new WaitForSeconds(messageDuration);

        messageText.gameObject.SetActive(false);
        messageCoroutine = null;
    }
}
